<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$db->prepare("INSERT INTO baremes_commission(compagnie_id,produit_id,type_calcul,taux,montant_fixe,date_debut,statut) VALUES(?,NULL,'pourcentage',?,NULL,?,'actif')")->execute([(int)$_POST['compagnie_id'],(float)$_POST['taux'],$_POST['date_debut']]);audit('CREATION','bareme_commission',(int)$db->lastInsertId());redirect('commissions/baremes.php');}$companies=$db->query("SELECT id,raison_sociale FROM compagnies WHERE statut='active' ORDER BY raison_sociale")->fetchAll();$rows=$db->query("SELECT b.*,c.raison_sociale FROM baremes_commission b JOIN compagnies c ON c.id=b.compagnie_id ORDER BY b.date_debut DESC")->fetchAll();$title='Barèmes';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell wide"><div class="page-heading"><h1 class="h3">Barèmes de commission</h1><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><form method="post" class="card card-body mb-3"><?= csrf_field() ?><div class="row g-2"><div class="col-md-5"><select name="compagnie_id" class="form-select" required><?php foreach($companies as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['raison_sociale']) ?></option><?php endforeach ?></select></div><div class="col-md-3"><input type="number" step=".01" min="0" name="taux" class="form-control" placeholder="Taux %" required></div><div class="col-md-3"><input type="date" name="date_debut" class="form-control" value="<?= date('Y-m-d') ?>" required></div><div class="col-md-1"><button class="btn btn-primary">+</button></div></div></form><div class="card"><table class="table mb-0"><thead><tr><th>Compagnie</th><th>Taux</th><th>Début</th><th>Statut</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['raison_sociale']) ?></td><td><?= e((string)$r['taux']) ?> %</td><td><?= e($r['date_debut']) ?></td><td><?= e($r['statut']) ?></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
